"""
pi_ai/types.py
──────────────
Unified message and event types shared across all providers.
All provider-specific formats are normalised into these structures.
"""

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any, Literal

# ──────────────────────────────────────────────────────────────────────────────
# Content block types (inside a message)
# ──────────────────────────────────────────────────────────────────────────────

@dataclass
class TextBlock:
    type: Literal["text"] = "text"
    text: str = ""


@dataclass
class ThinkingBlock:
    """Extended thinking / reasoning trace from the model."""
    type: Literal["thinking"] = "thinking"
    text: str = ""


@dataclass
class ToolCallBlock:
    """A tool invocation requested by the model."""
    type: Literal["tool_call"] = "tool_call"
    id: str = ""          # unique call id (e.g. "toolu_01ABC")
    name: str = ""        # tool name
    args: dict[str, Any] = field(default_factory=dict)
    args_raw: str = ""    # raw JSON string (for streaming display)


@dataclass
class ToolResultBlock:
    """The result of a tool execution fed back to the model."""
    type: Literal["tool_result"] = "tool_result"
    tool_call_id: str = ""
    content: str = ""          # text sent TO the model
    details: Any = None        # structured data for the UI (NOT sent to model)
    is_error: bool = False


ContentBlock = TextBlock | ThinkingBlock | ToolCallBlock | ToolResultBlock


# ──────────────────────────────────────────────────────────────────────────────
# Message types
# ──────────────────────────────────────────────────────────────────────────────

@dataclass
class UserMessage:
    role: Literal["user"] = "user"
    content: str | list[ContentBlock] = ""
    timestamp: int = 0


@dataclass
class AssistantMessage:
    role: Literal["assistant"] = "assistant"
    content: list[ContentBlock] = field(default_factory=list)
    stop_reason: Literal["stop", "tool_use", "length", "error", "aborted"] = "stop"
    usage: "TokenUsage | None" = None

    @property
    def text(self) -> str:
        """Concatenate all text blocks."""
        return "".join(b.text for b in self.content if isinstance(b, TextBlock))

    @property
    def tool_calls(self) -> list[ToolCallBlock]:
        return [b for b in self.content if isinstance(b, ToolCallBlock)]

    @property
    def thinking(self) -> str:
        parts = [b.text for b in self.content if isinstance(b, ThinkingBlock)]
        return "\n".join(parts)


@dataclass
class SystemMessage:
    role: Literal["system"] = "system"
    content: str = ""


Message = UserMessage | AssistantMessage | SystemMessage


# ──────────────────────────────────────────────────────────────────────────────
# Token usage and cost
# ──────────────────────────────────────────────────────────────────────────────

@dataclass
class TokenUsage:
    input_tokens: int = 0
    output_tokens: int = 0
    cache_read_tokens: int = 0
    cache_write_tokens: int = 0

    @property
    def total_tokens(self) -> int:
        return self.input_tokens + self.output_tokens

    def estimate_cost(self, model_cost: "Any") -> float:
        """Estimate USD cost given a TokenCost dataclass."""
        return (
            self.input_tokens     / 1_000_000 * model_cost.input
            + self.output_tokens  / 1_000_000 * model_cost.output
            + self.cache_read_tokens  / 1_000_000 * model_cost.cache_read
            + self.cache_write_tokens / 1_000_000 * model_cost.cache_write
        )


# ──────────────────────────────────────────────────────────────────────────────
# Streaming events emitted by providers
# ──────────────────────────────────────────────────────────────────────────────

@dataclass
class StreamStartEvent:
    type: Literal["stream_start"] = "stream_start"


@dataclass
class TextDeltaEvent:
    type: Literal["text_delta"] = "text_delta"
    delta: str = ""


@dataclass
class ThinkingDeltaEvent:
    type: Literal["thinking_delta"] = "thinking_delta"
    delta: str = ""


@dataclass
class ToolCallStartEvent:
    type: Literal["tool_call_start"] = "tool_call_start"
    tool_call_id: str = ""
    tool_name: str = ""


@dataclass
class ToolCallDeltaEvent:
    """Partial JSON of tool arguments (for live display)."""
    type: Literal["tool_call_delta"] = "tool_call_delta"
    tool_call_id: str = ""
    args_delta: str = ""    # raw JSON fragment


@dataclass
class ToolCallEndEvent:
    type: Literal["tool_call_end"] = "tool_call_end"
    tool_call: ToolCallBlock = field(default_factory=ToolCallBlock)


@dataclass
class StreamDoneEvent:
    type: Literal["stream_done"] = "stream_done"
    message: AssistantMessage = field(default_factory=AssistantMessage)


@dataclass
class StreamErrorEvent:
    type: Literal["stream_error"] = "stream_error"
    error: str = ""
    aborted: bool = False


StreamEvent = (
    StreamStartEvent
    | TextDeltaEvent
    | ThinkingDeltaEvent
    | ToolCallStartEvent
    | ToolCallDeltaEvent
    | ToolCallEndEvent
    | StreamDoneEvent
    | StreamErrorEvent
)


# ──────────────────────────────────────────────────────────────────────────────
# Tool definition (schema for the model)
# ──────────────────────────────────────────────────────────────────────────────

@dataclass
class ToolSchema:
    name: str
    description: str
    parameters: dict[str, Any]   # JSON Schema object


# ──────────────────────────────────────────────────────────────────────────────
# LLM call options
# ──────────────────────────────────────────────────────────────────────────────

@dataclass
class CallOptions:
    temperature: float = 0.0
    max_tokens: int | None = None
    reasoning: Literal["off", "minimal", "low", "medium", "high", "xhigh"] = "off"
    tools: list[ToolSchema] = field(default_factory=list)
    system: str = ""
    stop_sequences: list[str] = field(default_factory=list)


# ──────────────────────────────────────────────────────────────────────────────
# Context (the full conversation)
# ──────────────────────────────────────────────────────────────────────────────

@dataclass
class Context:
    """
    The full conversation state.
    Can be serialised to / deserialised from JSON (JSONL session files).
    Cross-provider: provider-specific blobs stored in _meta, not surfaced.
    """
    messages: list[Message] = field(default_factory=list)
    _meta: dict[str, Any] = field(default_factory=dict)  # internal blobs

    def add_user(self, text: str, timestamp: int = 0) -> None:
        import time
        self.messages.append(UserMessage(content=text, timestamp=timestamp or int(time.time() * 1000)))

    def add_assistant(self, msg: AssistantMessage) -> None:
        self.messages.append(msg)

    def add_tool_result(self, result: ToolResultBlock) -> None:
        # Tool results go into a user message in most providers
        self.messages.append(UserMessage(content=[result]))

"""
pi_ai/providers/anthropic_provider.py
──────────────────────────────────────
Anthropic Messages API adapter.
Normalises Anthropic's SSE stream → unified StreamEvent sequence.

Handles:
  - Extended thinking (budget_tokens)
  - Tool calling (with streaming)
  - Prompt caching token counts
  - Cross-provider context handoff (thinking → <thinking> tags)
"""

from __future__ import annotations

import json
from typing import AsyncIterator

from pi_agent.pi_ai.providers.base import BaseProvider
from pi_agent.pi_ai.types import (
    AssistantMessage,
    CallOptions,
    Context,
    StreamDoneEvent,
    StreamErrorEvent,
    StreamEvent,
    StreamStartEvent,
    TextBlock,
    TextDeltaEvent,
    ThinkingBlock,
    ThinkingDeltaEvent,
    TokenUsage,
    ToolCallBlock,
    ToolCallDeltaEvent,
    ToolCallEndEvent,
    ToolCallStartEvent,
    ToolResultBlock,
    UserMessage,
    SystemMessage,
)

# Reasoning level → budget_tokens mapping
_REASONING_BUDGET: dict[str, int] = {
    "off":     0,
    "minimal": 1_024,
    "low":     2_048,
    "medium":  8_000,
    "high":    16_000,
    "xhigh":   32_000,
}


class AnthropicProvider(BaseProvider):
    """Adapter for Anthropic's Messages API."""

    async def stream(
        self,
        context: Context,
        options: CallOptions,
        base_url: str | None = None,
    ) -> AsyncIterator[StreamEvent]:
        try:
            import anthropic
        except ImportError:
            raise ImportError("pip install anthropic")

        api_key = self._resolve_api_key("ANTHROPIC_API_KEY")
        client = anthropic.AsyncAnthropic(
            api_key=api_key,
            base_url=base_url,
        )

        # Build messages list
        messages = self._build_messages(context)

        # Build kwargs
        kwargs: dict = {
            "model": options.max_tokens and options.max_tokens or "claude-sonnet-4-5",
            "messages": messages,
            "max_tokens": options.max_tokens or 16_384,
        }
        if options.system:
            kwargs["system"] = options.system
        if options.tools:
            kwargs["tools"] = [
                {
                    "name": t.name,
                    "description": t.description,
                    "input_schema": t.parameters,
                }
                for t in options.tools
            ]
        if options.reasoning != "off":
            budget = _REASONING_BUDGET.get(options.reasoning, 8_000)
            kwargs["thinking"] = {"type": "enabled", "budget_tokens": budget}

        yield StreamStartEvent()

        # Accumulated state
        text_parts: list[str] = []
        thinking_parts: list[str] = []
        tool_calls: list[ToolCallBlock] = []
        usage = TokenUsage()
        stop_reason = "stop"

        try:
            async with client.messages.stream(**kwargs) as stream:
                async for event in stream:
                    event_type = type(event).__name__

                    if event_type == "RawContentBlockStartEvent":
                        block = event.content_block
                        if block.type == "thinking":
                            pass  # will accumulate via delta
                        elif block.type == "tool_use":
                            tc = ToolCallBlock(id=block.id, name=block.name)
                            tool_calls.append(tc)
                            yield ToolCallStartEvent(
                                tool_call_id=block.id,
                                tool_name=block.name,
                            )

                    elif event_type == "RawContentBlockDeltaEvent":
                        delta = event.delta
                        delta_type = type(delta).__name__

                        if delta_type == "TextDelta":
                            text_parts.append(delta.text)
                            yield TextDeltaEvent(delta=delta.text)

                        elif delta_type == "ThinkingDelta":
                            thinking_parts.append(delta.thinking)
                            yield ThinkingDeltaEvent(delta=delta.thinking)

                        elif delta_type == "InputJSONDelta":
                            if tool_calls:
                                tool_calls[-1].args_raw += delta.partial_json
                                yield ToolCallDeltaEvent(
                                    tool_call_id=tool_calls[-1].id,
                                    args_delta=delta.partial_json,
                                )

                    elif event_type == "RawContentBlockStopEvent":
                        # Finalise tool call JSON
                        if tool_calls and tool_calls[-1].args_raw and not tool_calls[-1].args:
                            try:
                                tool_calls[-1].args = json.loads(tool_calls[-1].args_raw)
                            except json.JSONDecodeError:
                                tool_calls[-1].args = {}
                            yield ToolCallEndEvent(tool_call=tool_calls[-1])

                    elif event_type == "RawMessageDeltaEvent":
                        if hasattr(event, "delta") and hasattr(event.delta, "stop_reason"):
                            sr = event.delta.stop_reason
                            stop_reason = {
                                "end_turn":   "stop",
                                "tool_use":   "tool_use",
                                "max_tokens": "length",
                            }.get(sr or "", "stop")
                        if hasattr(event, "usage"):
                            usage.output_tokens += getattr(event.usage, "output_tokens", 0)

                    elif event_type == "RawMessageStartEvent":
                        u = event.message.usage
                        usage.input_tokens = getattr(u, "input_tokens", 0)
                        usage.cache_read_tokens = getattr(u, "cache_read_input_tokens", 0)
                        usage.cache_write_tokens = getattr(u, "cache_creation_input_tokens", 0)

        except Exception as exc:
            aborted = "cancel" in str(exc).lower() or "abort" in str(exc).lower()
            yield StreamErrorEvent(error=str(exc), aborted=aborted)
            return

        # Build final AssistantMessage
        content_blocks = []
        if thinking_parts:
            content_blocks.append(ThinkingBlock(text="".join(thinking_parts)))
        if text_parts:
            content_blocks.append(TextBlock(text="".join(text_parts)))
        content_blocks.extend(tool_calls)

        msg = AssistantMessage(
            content=content_blocks,
            stop_reason=stop_reason,
            usage=usage,
        )
        yield StreamDoneEvent(message=msg)

    def _build_messages(self, context: Context) -> list[dict]:
        """Convert Context messages to Anthropic API format."""
        result = []
        for msg in context.messages:
            if isinstance(msg, SystemMessage):
                continue  # system goes in top-level kwarg
            elif isinstance(msg, UserMessage):
                if isinstance(msg.content, str):
                    result.append({"role": "user", "content": msg.content})
                else:
                    # content is a list of ContentBlocks
                    blocks = []
                    for block in msg.content:
                        if isinstance(block, ToolResultBlock):
                            blocks.append({
                                "type": "tool_result",
                                "tool_use_id": block.tool_call_id,
                                "content": block.content,
                                "is_error": block.is_error,
                            })
                    result.append({"role": "user", "content": blocks})
            elif isinstance(msg, AssistantMessage):
                blocks = []
                for block in msg.content:
                    if isinstance(block, TextBlock):
                        blocks.append({"type": "text", "text": block.text})
                    elif isinstance(block, ThinkingBlock):
                        # Cross-provider: convert to tagged text
                        blocks.append({
                            "type": "text",
                            "text": f"<thinking>{block.text}</thinking>",
                        })
                    elif isinstance(block, ToolCallBlock):
                        blocks.append({
                            "type": "tool_use",
                            "id": block.id,
                            "name": block.name,
                            "input": block.args,
                        })
                if blocks:
                    result.append({"role": "assistant", "content": blocks})
        return result
